
/* ==========================================================
   JOY-CON GAMEPAD VIEWER SKIN — NEW ZIP VERSION
   555 x 631 native canvas
   - transparent page
   - hides Gamepad Viewer chrome
   - hides player-light block
   - controller sits at top center
   - smooth analog-stick motion
   ========================================================== */

/* ---------- PAGE / GAMEPAD VIEWER CLEANUP ---------- */
html, body {
    margin: 0 !important;
    padding: 0 !important;
    width: 100% !important;
    height: 100% !important;
    overflow: hidden !important;
    background: transparent !important;
}

/* Hide Gamepad Viewer navigation/header/footer/UI */
header,
footer,
nav,
.navbar,
.nav,
.menu,
.topbar,
.header,
#header,
#menu,
#navbar,
#footer,
.social,
.controls,
.gpv-menu,
.gpv-header {
    display: none !important;
}

/* Remove large page offsets/padding used by the website */
body,
#content,
.content,
.container,
.container-fluid,
.viewer,
.gamepad,
.gamepad-container,
.controllers {
    margin-top: 0 !important;
    padding-top: 0 !important;
}

/* ---------- CONTROLLER BASE ---------- */
.controller.custom {
    position: fixed !important;
    top: 0 !important;
    left: 50% !important;
    width: 555px !important;
    height: 631px !important;
    margin: 0 !important;
    padding: 0 !important;
    transform: translateX(-50%) !important;
    background: url("data:image/png;base64,") no-repeat 0 0 !important;
    background-size: 555px 631px !important;
    z-index: 999999 !important;
}

.custom.disconnected {
    background-image: url("data:image/png;base64,") !important;
}

.custom.disconnected > div {
    display: none !important;
}

/* Kill inherited/default controller artwork */
.custom .trigger,
.custom .bumper,
.custom .button,
.custom .face,
.custom .back,
.custom .start,
.custom .stick,
.custom .quadrant,
.custom .guide {
    box-shadow: none !important;
    border: 0 !important;
    border-radius: 0 !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-size: contain !important;
}

/* Full-canvas wrappers so child positions use native coordinates */
.custom .triggers,
.custom .bumpers,
.custom .arrows,
.custom .abxy,
.custom .sticks,
.custom .dpad {
    position: absolute !important;
    left: 0 !important;
    top: 0 !important;
    width: 555px !important;
    height: 631px !important;
    margin: 0 !important;
    padding: 0 !important;
}

/* ---------- REMOVE THE PLAYER LED BLOCK ---------- */
.custom .quadrant,
.custom .quadrants {
    display: none !important;
}

/* ---------- ZL / ZR ---------- */
.custom .trigger {
    position: absolute !important;
    margin: 0 !important;
    float: none !important;
}

.custom .trigger.left {
    left: 0 !important;
    top: 0 !important;
    width: 228px !important;
