/* ---------- ANALOG STICKS ---------- */
.custom .stick {
    position: absolute !important;
    opacity: 1 !important;
    margin: 0 !important;
    transform-origin: 50% 50% !important;

    /* Smooth live axis updates without adding much lag */
    transition:
        transform 38ms cubic-bezier(.20,.70,.30,1),
        background-image 25ms linear !important;

    will-change: transform !important;
}

.custom .stick.left {
    left: 34px !important;
    top: 121px !important;
    width: 135px !important;
    height: 138px !important;
    background-image: url("data:image/png;base64,") !important;
}

.custom .stick.right {
    left: 378px !important;
    top: 300px !important;
    width: 136px !important;
    height: 139px !important;
    background-image: url("data:image/png;base64,") !important;
}

.custom .stick.left.pressed {
    background-image: url("data:image/png;base64,") !important;
}

.custom .stick.right.pressed {
    background-image: url("data:image/png;base64,") !important;
}

