}

.custom.half {
    margin-top: 0 !important;
}

.custom *::before,
.custom *::after {
    box-shadow: none !important;
}

@media (prefers-reduced-motion: reduce) {
    .custom .stick {
        transition: none !important;
    }
}

/* ==========================================================
   MOVING STICKS ONLY — BASE HAS NO STICKS
   ========================================================== */

/* The base PNG has had both analog sticks removed.
   These exact PNGs are now the live moving stick artwork. */

.custom .sticks {
    position: absolute !important;
    left: 0 !important;
    top: 0 !important;
    width: 555px !important;
    height: 631px !important;
    overflow: visible !important;
    pointer-events: none !important;
}

/* IMPORTANT: GPV owns transform on .stick.
   Do NOT set transform here, or analog movement breaks. */
.custom .stick,
.custom .stick.pressed {
    position: absolute !important;
    opacity: 1 !important;
    margin: 0 !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    transform-origin: 50% 50% !important;
    will-change: transform !important;
    transition: transform 18ms linear !important;
    z-index: 40 !important;
}

.custom .stick.left,
.custom .stick.left.pressed {
    left: 34px !important;
    top: 121px !important;
    width: 135px !important;
    height: 138px !important;
    background-image: url("data:image/png;base64,") !important;
    background-size: 135px 138px !important;
}

.custom .stick.right,
.custom .stick.right.pressed {
    left: 378px !important;
    top: 300px !important;
    width: 136px !important;
    height: 139px !important;
    background-image: url("data:image/png;base64,") !important;
    background-size: 136px 139px !important;
}

/* Kill any default white GPV indicator/dot. */
.custom .stick::before,
.custom .stick::after {
    content: none !important;
    display: none !important;
}

/* Keep player indicator hidden and page OBS-clean. */
.custom .quadrant,
.custom .quadrants {
    display: none !important;
}

html,
body {
    margin: 0 !important;
    padding: 0 !important;
    overflow: hidden !important;
    background: transparent !important;
}
